// navigation regions, not coordinate transforms for player/quest positions.
const overview = (uiMapId, name, artwork, kind, parentId = null) => ({
  uiMapId, name, kind, parentId, edition:'tbc', width:1024, height:683,
  url:`https://wow.zamimg.com/images/wow/tbc/maps/enus/original/${artwork}.jpg`,
});
const overviews = [
  overview(946, 'Worlds', -4, 'cosmic'),
  overview(947, 'Azeroth', -1, 'world', 946),
  overview(1414, 'Kalimdor', -6, 'continent', 947),
  overview(1415, 'Eastern Kingdoms', -3, 'continent', 947),
  overview(1945, 'Outland', -2, 'continent', 946),
];
const regions = new Map();
function region(id, parentId, points) {
  regions.set(id, {parentId, polygon:points.map(([x,y]) => [x/1024,y/683])});
}
