// City entrances on their surrounding zone maps. Small, visible buttons use
// fixed screen-size hit targets; the artwork underneath remains unobstructed.
const cities = [
  [1453,1429,.16,.22], [1455,1426,.55,.38], [1458,1420,.62,.65],
  [1454,1411,.45,.11], [1456,1412,.39,.28], [1457,1438,.27,.56],
  [1947,1943,.24,.45], [1954,1941,.54,.40], [1955,1952,.30,.23],
];
const battlegrounds = new Set([1459,1460,1461,1956]);

export function buildMapCatalog(zones) {
  const catalog = [...overviews, ...zones.map(map => ({...map, kind:battlegrounds.has(map.uiMapId) ? 'battleground' : 'zone', parentId:946}))];
  for (const map of catalog) if (regions.has(map.uiMapId)) Object.assign(map,regions.get(map.uiMapId));
  for (const [id,parentId,x,y] of cities) {
    const map = catalog.find(map => map.uiMapId === id);
    if (map) Object.assign(map,{kind:'city',parentId,entrance:{x,y}});
  }
  return catalog;
}

export function mapViewport(width, height, imageWidth, imageHeight, zoom = 1, pan = {x:0,y:0}) {
  const base = Math.min(Math.max(1,width-32)/imageWidth,Math.max(1,height-85)/imageHeight);
  const w = imageWidth*base*zoom, h = imageHeight*base*zoom;
  return {x:(width-w)/2+pan.x,y:(height-h)/2+pan.y,w,h};
}

export function mapPoint(x, y, viewport) {
  if (!viewport || viewport.w <= 0 || viewport.h <= 0) return null;
  const point = {x:(x-viewport.x)/viewport.w,y:(y-viewport.y)/viewport.h};
  return point.x < 0 || point.x > 1 || point.y < 0 || point.y > 1 ? null : point;
}

export function containsPoint(polygon, point) {
  let inside = false;
  for (let i=0,j=polygon.length-1;i<polygon.length;j=i++) {
    const [xi,yi]=polygon[i], [xj,yj]=polygon[j];
    if ((yi>point.y)!==(yj>point.y) && point.x<(xj-xi)*(point.y-yi)/(yj-yi)+xi) inside=!inside;
  }
  return inside;
}

export function hitTestMap(children, x, y, viewport) {
  const point = mapPoint(x,y,viewport);
  if (!point) return null;
  return children.find(map => map.entrance && Math.hypot(x-viewport.x-map.entrance.x*viewport.w,y-viewport.y-map.entrance.y*viewport.h)<=16)
    || children.find(map => map.polygon && containsPoint(map.polygon,point)) || null;
}
